P = [
 dict(pmid='43021198', doi='10.1186/s12889-026-29056-8', journal='BMC Public Health', title='Independent and joint effects of apparent temperature and ambient air pollution on endometriosis-related outpatient visits in Beijing, China: a time-series study.', short='Peking University First Hospital 39015 endometriosis outpatient visits 2022-2024 DLNM apparent temperature PM2.5 PM10 ozone interaction', design='Time series', pm='Daily PM2.5, PM10 and O3 (monitoring source not stated)', geo='China (Beijing)', endpoint='Daily endometriosis-related outpatient visits', tier='B', basis='Not stated', affil='Peking University First Hospital, China; Peking University First Hospital, China', n='Quasi-Poisson DLNM time series of 39,015 endometriosis-related outpatient visits at one Beijing hospital, 2022-2024. Single-pollutant cumulative risks: PM2.5 lag 0-7 RR 1.109 (1.044-1.177) and PM10 lag 0-6 RR 1.070 (1.014-1.128), increments not stated in the abstract; high apparent temperature (P90 vs median) RR 1.126 (1.078-1.177) over lag 0-14; a positive additive interaction for temperature with ozone (IRR 1.114, 1.053-1.180), not with PM. Outpatient visits for a chronic condition reflect care-seeking and scheduling as much as symptom flares, a single hospital limits generalisability, and 2022 includes COVID-era access disruption. Relevance: indirect - a new short-term endpoint for PM; exposure is city-wide, so within-city contrast is untested.', sub=corpus.REPR),
 dict(pmid='43020481', doi='10.1183/13993003.01336-2026', journal='Eur Respir J', title='Ambient Air Pollution, Climate, Land Use, and Small-Area Incidence of Interstitial Lung Disease: A Bi-National Semi-Ecological Study.', short='Sydney bi-national semi-ecological small-area interstitial lung disease incidence air pollution climate land use metadata only', design='Metadata only - no abstract available', pm='Ambient air pollution (per title; metrics not available)', geo='Australia; not confirmed (bi-national)', endpoint='Small-area ILD incidence (per title)', tier='C', basis='Not stated', affil='The University of Sydney, Australia; The University of Sydney, Australia', n='Metadata only. European Respiratory Journal accepted manuscript with no abstract in PubMed at harvest. The title describes a bi-national semi-ecological study relating ambient air pollution, climate and land use to small-area incidence of interstitial lung disease; the second country, the pollutants, exposure model and effect estimates cannot be confirmed and no finding is asserted. Carried because ILD is an under-studied PM endpoint and small-area designs depend directly on the spatial resolution of the exposure surface. Recheck for the abstract in the weekly sweep. Relevance: possible - small-area exposure assignment where denser monitoring would reduce misclassification.', sub=corpus.RESP),
 dict(pmid='43020048', doi='10.1123/jpah.2026-0332', journal='J Phys Act Health', title='Effects of Acute Exercise Under Different Environmental Stressors on Cardiorespiratory Function in Healthy Adults: A Systematic Review With Pairwise and Network Meta-Analyses.', short='Guangxi Minzu network meta-analysis 26 controlled trials 344 adults acute exercise heat cold hypoxia air pollution ventilation VO2 HR', design='Systematic review + network meta-analysis', pm='Air pollution exposures in controlled exercise trials (types not specified in abstract)', geo='Global', endpoint='Minute ventilation, oxygen uptake, heart rate during acute exercise', tier='B', basis='Review / no primary exposure', affil='Guangxi Minzu University, China; Xinjiang Hetian College, China', n='Network meta-analysis of 26 controlled trials (344 healthy adults) comparing acute exercise under heat, cold, hypoxia and air pollution against matched controls. Most pairwise contrasts were non-significant; hypoxia ranked highest for minute ventilation, heat for oxygen uptake and heart rate, and air pollution imposed the weakest effects on every outcome. No funnel asymmetry was found, though with 26 small trials that test has little power. Pollution exposures (diesel exhaust, PM, ozone) are pooled into one node in the abstract, so the null says nothing about any specific particle dose, and acute cardiorespiratory responses are not the pathway through which PM harms exercisers. Relevance: indirect - acute exercise physiology is an insensitive endpoint for PM.', sub=corpus.CVM),
 dict(pmid='43019174', doi='10.1038/s41598-026-64861-6', journal='Sci Rep', title="Observational evaluation of children's respirator donning ability in Indonesia and Nepal.", short='Durham Kathmandu Bandung 348 children 6-13 years KN95-style respirator unaided donning seven criteria nose clip', design='Observational evaluation', pm='None measured; respirator use as protection against airborne particulates', geo='Nepal; Indonesia', endpoint='Correct unaided respirator donning', tier='C', basis='Not stated', affil='Durham University, United Kingdom; Durham University, United Kingdom', n='348 children aged 6-13 in Kathmandu and Bandung donned two child-marketed KN95-style respirators without guidance. Only 21.8% met all seven essential donning criteria, though 79.6% completed at least five; nose-clip shaping was the commonest error. Older children and girls did better, prior KN95 experience improved technique and confidence, and respirator design mattered. Donning criteria are a proxy: no quantitative fit factor or inward leakage was measured, so the protective consequence of each error is inferred. Relevance: direct for mitigation - individual protection advice issued off sensor-network alerts assumes a fit that four in five children here did not achieve.', sub=corpus.BURD),
]
